// SPDX-License-Identifier: Apache-2.0
// Co-simulation: LiteDRAM controller (DFI master) + sdram_phy_core + pin model.
//
// The controller is generated by sim/gen_litedram_ctrl.py with
// read_latency = CL - 2 + CDC_LATENCY + 1 = 7.  This TB checks that the PHY's
// DFI read return really is 7 cycles (CDC output register included), then does write/read/masked-write/
// row-change/turnaround traffic through the native port.
`timescale 1ns/1ps
`default_nettype none

module tb_litedram_cosim;
    localparam integer AB = 13;
    localparam integer BB = 2;
    localparam integer DB = 8;
    localparam integer CL = 2;
    localparam integer CMD = AB + BB + 6;

    reg clk = 1'b0;
    reg rst = 1'b1;
    always #5 clk = ~clk;

    // Native user port (bank 0 only).
    reg         cmd_valid = 0;
    wire        cmd_ready;
    reg         cmd_we = 0;
    reg  [21:0] cmd_addr = 0;
    wire        cmd_lock;
    wire        wdata_ready;
    wire        rdata_valid;
    reg  [7:0]  wdata = 0;
    reg         wdata_we = 0;
    wire [7:0]  rdata;

    // DFI
    wire [12:0] dfi_a;
    wire [1:0]  dfi_ba;
    wire        dfi_ras, dfi_cas, dfi_we, dfi_cs, dfi_cke;
    wire        dfi_odt, dfi_reset, dfi_act;
    wire [7:0]  dfi_wrdata;
    wire        dfi_wren;
    wire        dfi_wrmask;
    wire        dfi_rden;
    wire [7:0]  dfi_rddata;
    wire        dfi_rdvalid;

    wire [CMD-1:0] pad_cmd;
    wire [DB-1:0]  pad_dq;
    wire           pad_ck;
    wire [DB-1:0]  dq_core_o, dq_core_i;
    wire           dq_core_oe;
    wire           cap_clk, capture_ready, pad_ready, contention, ck_active;
    wire           latency_error, turnaround_busy;
    assign dfi_act = 1'b1;

    wire [AB-1:0] a;
    wire [BB-1:0] ba;
    wire ras_n, cas_n, we_n, cs_n, cke;
    wire [DB/8-1:0] dm;
    wire fault;
    wire [2:0] fault_code;

    integer errors = 0;
    integer rd_en_cycle = -1;
    integer rd_latency = -1;
    integer cyc = 0;

    `define CHECK(cond) \
        if (!(cond)) begin \
            $display("FAIL line %0d: %s", `__LINE__, `"cond`"); \
            errors = errors + 1; \
        end

    always @(posedge clk) begin
        if (dfi_wren)
            $display("  WRDATA t=%0t d=%h mask=%b we=%b oe=%b cmd_dq=%h", $time,
                     dfi_wrdata, dfi_wrmask, wdata_we, dq_core_oe, pad_dq);
        if (dfi_rden)
            $display("  RDEN t=%0t oe=%b cmd_dq=%h pad=%h", $time,
                     dq_core_oe, dq_core_o, pad_dq);
        if (dfi_rdvalid)
            $display("  RDVALID t=%0t d=%h", $time, dfi_rddata);
        if (dfi_cs == 1'b0 && !(dfi_ras && dfi_cas && dfi_we))
            $display("  DFI CMD t=%0t ras=%b cas=%b we=%b a=%h ba=%h", $time,
                     dfi_ras, dfi_cas, dfi_we, dfi_a, dfi_ba);
    end

    always @(posedge clk) begin
        cyc <= cyc + 1;
        if (cyc < 200 && (cyc % 10 == 0))
            $display("  [%0d t=%0t] cmd_valid=%b ready=%b dfi_cs=%b ras=%b cas=%b we=%b a=%h",
                     cyc, $time, cmd_valid, cmd_ready, dfi_cs, dfi_ras, dfi_cas, dfi_we, dfi_a);
    end

    // DFI read-return latency: rddata_en -> rddata_valid must be 7.
    always @(posedge clk) begin
        if (dfi_rden) rd_en_cycle <= cyc;
        if (dfi_rdvalid && rd_en_cycle >= 0 && rd_latency < 0)
            rd_latency <= cyc - rd_en_cycle;
    end

    litedram_ctrl ctrl (
        .sys_clk(clk), .sys_rst(rst),
        .interface_bank0_valid(cmd_valid),
        .interface_bank0_ready(cmd_ready),
        .interface_bank0_we(cmd_we),
        .interface_bank0_addr(cmd_addr),
        .interface_bank0_lock(cmd_lock),
        .interface_bank0_wdata_ready(wdata_ready),
        .interface_bank0_rdata_valid(rdata_valid),
        .interface_wdata(wdata), .interface_wdata_we(wdata_we),
        .interface_rdata(rdata),
        .dfi_p0_address(dfi_a), .dfi_p0_bank(dfi_ba),
        .dfi_p0_cas_n(dfi_cas), .dfi_p0_cs_n(dfi_cs),
        .dfi_p0_ras_n(dfi_ras), .dfi_p0_we_n(dfi_we),
        .dfi_p0_cke(dfi_cke), .dfi_p0_odt(dfi_odt),
        .dfi_p0_reset_n(dfi_reset), .dfi_p0_act_n(dfi_act),
        .dfi_p0_wrdata(dfi_wrdata), .dfi_p0_wrdata_en(dfi_wren),
        .dfi_p0_wrdata_mask(dfi_wrmask), .dfi_p0_rddata_en(dfi_rden),
        .dfi_p0_rddata(dfi_rddata), .dfi_p0_rddata_valid(dfi_rdvalid)
    );

    sdram_phy_core #(.CL(CL), .CDC_LATENCY(6)) dut (
        .clk(clk), .rst(rst),
        .dfi_address(dfi_a), .dfi_bank(dfi_ba),
        .dfi_ras_n(dfi_ras), .dfi_cas_n(dfi_cas), .dfi_we_n(dfi_we),
        .dfi_cs_n(dfi_cs), .dfi_cke(dfi_cke),
        .dfi_odt(dfi_odt), .dfi_reset_n(dfi_reset), .dfi_act_n(dfi_act),
        .dfi_wrdata(dfi_wrdata), .dfi_wrdata_en(dfi_wren),
        .dfi_wrdata_mask(dfi_wrmask), .dfi_rddata_en(dfi_rden),
        .dfi_rddata(dfi_rddata), .dfi_rddata_valid(dfi_rdvalid),
        .io_power_ok(1'b1), .pad_config(8'b0),
        .phase_clks(4'b0), .phase_clocks_ready(1'b0),
        .phase_sel(2'b0), .phase_sel_valid(1'b0),
        .ck_phase_clks(4'b0), .ck_phase_clocks_ready(1'b0),
        .ck_phase_sel(2'b0),
        .cmd_o(pad_cmd), .dq_o(dq_core_o), .dq_oe(dq_core_oe),
        .dq_i(dq_core_i), .ck_o(pad_ck),
        .cap_clk(cap_clk), .capture_ready(capture_ready),
        .turnaround_busy(turnaround_busy), .pad_ready(pad_ready),
        .contention(contention), .ck_active(ck_active),
        .read_latency_error(latency_error)
    );

    pad_cell_generic u_dq (
        .core_out(dq_core_o), .core_oe(dq_core_oe),
        .core_in(dq_core_i), .pad(pad_dq),
        .power_ok(1'b1), .driving(), .contention()
    );

    assign {a, ba, ras_n, cas_n, we_n, cs_n, cke, dm} = pad_cmd;

    sdram_model #(
        .ADDR_BITS(AB), .BANK_BITS(BB), .DATA_BITS(DB),
        .ROW_BITS(13), .COL_BITS(9)
    ) model (
        .ck(pad_ck), .cke(cke), .cs_n(cs_n),
        .ras_n(ras_n), .cas_n(cas_n), .we_n(we_n),
        .a(a), .ba(ba), .dm(dm), .dq(pad_dq),
        .fault(fault), .fault_code(fault_code)
    );

    task automatic wr(input [21:0] addr, input [7:0] data, input mask);
        begin
            $display("wr start addr=%h t=%0t", addr, $time);
            @(negedge clk);
            cmd_valid = 1'b1; cmd_we = 1'b1; cmd_addr = addr;
            wdata = data; wdata_we = mask;
            @(posedge clk);
            while (!cmd_ready) @(posedge clk);
            @(negedge clk);
            cmd_valid = 1'b0; cmd_we = 1'b0;
            // Leave wdata/wdata_we stable: LiteDRAM forwards them to the
            // DFI at the WRITE command, which can be many cycles later.
            $display("wr accepted t=%0t", $time);
        end
    endtask

    task automatic rd(input [21:0] addr, output [7:0] data);
        begin
            @(negedge clk);
            cmd_valid = 1'b1; cmd_we = 1'b0; cmd_addr = addr;
            @(posedge clk);
            while (!cmd_ready) @(posedge clk);
            @(negedge clk);
            cmd_valid = 1'b0;
            // Native rdata_valid pulses when the command is accepted; the
            // actual word appears on the DFI bus `read_latency` later.
            while (!dfi_rdvalid) @(posedge clk);
            data = dfi_rddata;
            $display("rd addr=%h data=%h t=%0t", addr, data, $time);
        end
    endtask

    reg [7:0] got;

    initial begin
        #1000;
        $display("T1000 reached");
    end

    initial begin
        $display("start t=%0t", $time);
        $dumpfile("tb_litedram_cosim.vcd");
        $dumpvars(0, tb_litedram_cosim);
        repeat (20) @(posedge clk);
        $display("out of reset t=%0t", $time);
        rst <= 1'b0;
        repeat (20) @(posedge clk);

        // Row 0 / col 0
        wr(22'h000000, 8'hA5, 1'b1);
        rd(22'h000000, got);
        `CHECK(got == 8'hA5)

        // Row 1 / col 0 (row change: PRE -> ACT -> RD)
        wr(22'h000200, 8'h5A, 1'b1);
        rd(22'h000200, got);
        `CHECK(got == 8'h5A)

        // Masked write must not change the cell.
        wr(22'h000000, 8'h3C, 1'b0);
        rd(22'h000000, got);
        `CHECK(got == 8'hA5)

        // Read -> write turnaround on the same row.
        rd(22'h000200, got);
        `CHECK(got == 8'h5A)
        wr(22'h000200, 8'hC3, 1'b1);
        rd(22'h000200, got);
        `CHECK(got == 8'hC3)

        repeat (800) @(posedge clk);   // let the refresher run
        rd(22'h000200, got);
        `CHECK(got == 8'hC3)

        $display("MEASURED rd_latency=%0d", rd_latency);
        `CHECK(rd_latency == 7)
        `CHECK(latency_error == 1'b0)
        `CHECK(fault == 1'b0)
        `CHECK(contention == 1'b0)

        if (errors == 0) $display("PASS litedram_cosim");
        else             $display("FAIL litedram_cosim (%0d errors)", errors);
        $finish;
    end

    initial begin
        repeat (4000) @(posedge clk);
        $display("TIMEOUT litedram_cosim (rd_latency=%0d)", rd_latency);
        $finish;
    end
endmodule
`default_nettype wire
